using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static class TelegraphGround11 {
 public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling)throw new Exception("Clean Edit");string original=SceneManager.GetActiveScene().path;EditorSceneManager.OpenScene("Assets/ShooterSurvival/Scenes/Tools/Jamsil.unity");try{var d=UnityEngine.Object.FindFirstObjectByType<Chapter45Director>();var p=d.hazards.Single(h=>h.name=="Wrong way kickboard").body.position;var rows=new List<object>();foreach(var f in UnityEngine.Object.FindObjectsByType<MeshFilter>(FindObjectsSortMode.None)){var r=f.GetComponent<Renderer>();if(r==null||!r.enabled||f.sharedMesh==null)continue;var box=r.bounds;if(p.x<box.min.x||p.x>box.max.x||p.z<box.min.z||p.z>box.max.z||box.min.y>.3f||box.max.y<0)continue;try{var v=f.sharedMesh.vertices;var tri=f.sharedMesh.triangles;float top=float.NegativeInfinity;for(int i=0;i<tri.Length;i+=3){var a=f.transform.TransformPoint(v[tri[i]]);var b=f.transform.TransformPoint(v[tri[i+1]]);var c=f.transform.TransformPoint(v[tri[i+2]]);float det=(b.z-c.z)*(a.x-c.x)+(c.x-b.x)*(a.z-c.z);if(Mathf.Abs(det)<.00001)continue;float u=((b.z-c.z)*(p.x-c.x)+(c.x-b.x)*(p.z-c.z))/det;float w=((c.z-a.z)*(p.x-c.x)+(a.x-c.x)*(p.z-c.z))/det;if(u<0||w<0||u+w>1)continue;float y=u*a.y+w*b.y+(1-u-w)*c.y;if(y>=0&&y<.5)top=Mathf.Max(top,y);}if(!float.IsInfinity(top))rows.Add(new{f.name,top});}catch{}}
 return new{position=new[]{p.x,p.y,p.z},surfaces=rows,readOnly=true};}finally{EditorSceneManager.OpenScene(original);}}
}
